using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;

public record ProjectWrite(string Name,Guid UnitId,Guid[] Chapters,Guid ManagerId,DateOnly StartsOn,DateOnly EndsOn,string Category="Community Service",string Description="",string Objectives="",string Location="",Guid? CommitteeId=null,Guid? BudgetId=null,Guid? EventId=null,Guid? ActivityId=null,int Revision=0);
public record VolunteerCheck(Guid MembershipId,DateTimeOffset? CheckedIn=null,DateTimeOffset? CheckedOut=null,string Note="");
public record VolunteerCorrection(DateTimeOffset CheckedIn,DateTimeOffset CheckedOut,DateTimeOffset ExpectedCheckedIn,DateTimeOffset? ExpectedCheckedOut,string Reason);
public record AchievementShare(Guid CategoryId);
public record ImpactWrite(Guid MetricId,string OutcomeKey,decimal Value,string Evidence,Guid? EvidenceId=null);
public class ServiceProjectService(AppDb db,Access a,CommunityService community){
 public IQueryable<ServiceProject> Visible(Guid tenant,Guid? workspace=null){var units=a.InWorkspace(a.Visible(tenant,"service.read"),tenant,workspace).Select(u=>u.Id);var mine=community.Mine(tenant).Select(m=>m.ChapterId);return db.Set<ServiceProject>().Where(p=>p.TenantId==tenant&&(p.UnitId!=null&&units.Contains(p.UnitId.Value)||db.Set<ProjectChapter>().Any(c=>c.TenantId==tenant&&c.ProjectId==p.Id&&(units.Contains(c.ChapterId)||((p.Status=="Approved"||p.Status=="Completed")&&mine.Contains(c.ChapterId))))));}
 public async Task<ServiceProject> Read(Guid tenant,Guid id){await a.Member(tenant);return await Visible(tenant).AsTracking().SingleOrDefaultAsync(p=>p.Id==id)??throw new AccessDeniedException();}
 public async Task<ServiceProject> Manage(Guid tenant,Guid id,string permission="service.manage"){var p=await Read(tenant,id);await a.Require(tenant,permission,p.UnitId);return p;}
 public async Task<Membership> Member(Guid tenant,Guid id,bool self=false){var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==id&&m.Status=="Active"&&m.EffectiveFrom<=DateTimeOffset.UtcNow&&(m.EndsAt==null||m.EndsAt>DateTimeOffset.UtcNow))??throw new DomainException("Choose a current active membership");if(self&&!await db.Persons.AnyAsync(p=>p.Id==m.PersonId&&p.UserId==a.UserId))throw new AccessDeniedException();return m;}
 public async Task Participant(ServiceProject p,Membership m){if(!await db.Set<ProjectChapter>().AnyAsync(c=>c.TenantId==p.TenantId&&c.ProjectId==p.Id&&c.ChapterId==m.ChapterId))throw new DomainException("Membership is outside the participating chapters");}
 public async Task Validate(Guid tenant,ProjectWrite r,FinanceService finance){if(r.Name.Trim().Length is <3 or >180||r.Description.Length>12000||r.Objectives.Length>4000||r.Location.Length>500||r.Category.Length is <1 or >120||r.EndsOn<r.StartsOn||r.EndsOn>r.StartsOn.AddYears(5))throw new DomainException("Check project name, dates, description and category");var chapters=r.Chapters.Append(r.UnitId).Distinct().ToArray();if(chapters.Length is <1 or >100)throw new DomainException("Choose up to 100 participating chapters");foreach(var chapter in chapters){await a.Require(tenant,"service.manage",chapter);if(!await db.Units.AnyAsync(u=>u.TenantId==tenant&&u.Id==chapter&&u.Status=="Active"&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")))throw new DomainException("Participating organizations must be active chapters");}var manager=await Member(tenant,r.ManagerId);if(!chapters.Contains(manager.ChapterId))throw new DomainException("Project manager must belong to a participating chapter");if(r.CommitteeId!=null&&!await db.Committees.AnyAsync(c=>c.TenantId==tenant&&c.Id==r.CommitteeId&&(c.UnitId==null||chapters.Contains(c.UnitId.Value))))throw new DomainException("Committee must serve a participating organization");if(r.BudgetId!=null){var budget=await db.Set<FinanceBudget>().SingleOrDefaultAsync(b=>b.TenantId==tenant&&b.Id==r.BudgetId&&b.UnitId==r.UnitId&&b.Status=="Approved")??throw new DomainException("Use an approved existing budget belonging to the lead chapter");await finance.Require(tenant,budget.EntityId,budget.UnitId);}if(r.EventId!=null){var e=await community.Event(tenant,r.EventId.Value);if(e.UnitId==null||!chapters.Contains(e.UnitId.Value))throw new DomainException("Linked event must belong to a participating chapter");}if(r.ActivityId!=null){var post=await community.Post(tenant,r.ActivityId.Value);if(post.UnitId==null||!chapters.Contains(post.UnitId.Value))throw new DomainException("Linked activity must belong to a participating chapter");}}
}
public static class ServiceEndpoints {
 public static void Map(RouteGroupBuilder api){var t=api.MapGroup("/societies/{tenant:guid}/service").RequireAuthorization().RequireRateLimiting("community");t.AddEndpointFilter(async(ctx,next)=>{await ctx.HttpContext.RequestServices.GetRequiredService<Access>().Member(Guid.Parse(ctx.HttpContext.Request.RouteValues["tenant"]!.ToString()!));return await next(ctx);});
  t.MapGet("/setup",async(Guid tenant,AppDb db,Access a)=>new{chapters=await a.Visible(tenant,"service.manage").Where(u=>db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")).OrderBy(u=>u.Name).Select(u=>new{u.Id,u.Name}).Take(1000).ToListAsync(),myMemberships=await db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)).Select(m=>new{m.Id,m.Number,m.ChapterId}).ToListAsync()});
  t.MapGet("/members",async(Guid tenant,string? search,AppDb db,Access a)=>{var units=a.Visible(tenant,"service.coordinate").Select(u=>u.Id);var q=db.Memberships.Where(m=>m.TenantId==tenant&&m.Status=="Active"&&(units.Contains(m.ChapterId)||db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)));if(!string.IsNullOrWhiteSpace(search))q=q.Where(m=>EF.Functions.ILike(m.Number,"%"+search+"%")||db.Persons.Any(p=>p.Id==m.PersonId&&EF.Functions.ILike(p.FullName,"%"+search+"%")));return await(from m in q join p in db.Persons on m.PersonId equals p.Id orderby p.FullName select new{m.Id,m.Number,p.FullName,m.ChapterId}).Take(100).ToListAsync();});
  t.MapPost("/achievements/certificates/{id:guid}/share",async(Guid tenant,Guid id,AchievementShare r,StudioService studio,CommunityService community,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);if(!await PlatformPolicy.WorkAllowed(db,tenant,"community"))throw new AccessDeniedException();var certificate=await studio.Read(tenant,id);await a.Require(tenant,"activities.official",certificate.UnitId);if(certificate.Kind!="Certificate"||certificate.Status!="Issued")throw new DomainException("Only an issued certificate can be shared as recognition");var tag="credential:"+id;var existing=await db.Set<ActivityPost>().SingleOrDefaultAsync(p=>p.TenantId==tenant&&p.Achievement&&p.Tags.Contains(tag));if(existing!=null)return Results.Ok(existing);var snapshot=JsonSerializer.Deserialize<CredentialSnapshot>(certificate.Snapshot,DesignSchema.Json)!;var title="Recognition · "+certificate.Category;var name=System.Net.WebUtility.HtmlEncode(snapshot.Fields.GetValueOrDefault("member.full_name","Member"));var body="<p>"+name+" received "+System.Net.WebUtility.HtmlEncode(certificate.Category)+" on "+certificate.IssueDate+".</p>";var post=new ActivityPost{TenantId=tenant,AuthorId=a.UserId};await ActivityEndpoints.Apply(post,new PostWrite(certificate.UnitId,r.CategoryId,body,Title:title,Official:true,Tags:[tag],Submit:true,Achievement:true),db,a,community);db.Add(post);community.Version(tenant,post.Id,"Post",0,post);a.Audit(tenant,"achievement.feed.requested",certificate.Id,new{postId=post.Id});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(post);});
  t.MapGet("/achievements",async(Guid tenant,Guid? membership,AppDb db,Access a)=>{var q=db.Memberships.Where(m=>m.TenantId==tenant&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId));if(membership!=null){var m=await db.Memberships.SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==membership)??throw new AccessDeniedException();if(!await q.AnyAsync(own=>own.Id==m.Id))await a.Require(tenant,"members.read",m.ChapterId);q=db.Memberships.Where(x=>x.TenantId==tenant&&x.Id==membership);}var ids=q.Select(m=>m.Id);return Results.Ok(new{verifiedHours=await db.Set<VolunteerAttendance>().Where(v=>v.TenantId==tenant&&ids.Contains(v.MembershipId)&&v.Status=="Verified").SumAsync(v=>v.Hours),projects=await(from v in db.Set<VolunteerAssignment>() join project in db.Set<ServiceProject>() on v.ProjectId equals project.Id where v.TenantId==tenant&&ids.Contains(v.MembershipId)&&v.Status=="Approved" select new{project.Id,project.Name,project.Status}).Distinct().Take(200).ToListAsync(),certificates=await db.Set<Credential>().Where(c=>c.TenantId==tenant&&ids.Contains(c.MembershipId)&&c.Kind=="Certificate"&&c.Status=="Issued").Select(c=>new{c.Id,c.Serial,c.Category,c.IssueDate}).Take(200).ToListAsync(),events=await(from attendance in db.Set<EventAttendance>() join registration in db.Set<EventRegistration>() on attendance.RegistrationId equals registration.Id join ev in db.Set<CommunityEvent>() on attendance.EventId equals ev.Id where attendance.TenantId==tenant&&!attendance.Voided&&registration.MembershipId!=null&&ids.Contains(registration.MembershipId.Value) select new{ev.Id,ev.Title,attendance.At}).Take(200).ToListAsync(),leadership=await(from o in db.OfficerAppointments join position in db.OfficerPositions on o.PositionId equals position.Id where o.TenantId==tenant&&ids.Contains(o.MembershipId)&&new[]{"Approved","Expired"}.Contains(o.Status) select new{o.Id,position.Name,o.StartsAt,o.EndsAt}).Take(200).ToListAsync()});});
  t.MapGet("/projects",async(Guid tenant,Guid? workspace,string? status,string? search,int? page,ServiceProjectService s,AppDb db)=>{var q=s.Visible(tenant,workspace);if(status!=null)q=q.Where(p=>p.Status==status);if(!string.IsNullOrWhiteSpace(search))q=q.Where(p=>EF.Functions.ILike(p.Name,"%"+search+"%"));return Results.Ok(new{total=await q.CountAsync(),items=await q.OrderByDescending(p=>p.StartsOn).ThenBy(p=>p.Id).Skip(Math.Max(0,(page??1)-1)*50).Take(50).ToListAsync()});});
  t.MapPost("/projects",async(Guid tenant,ProjectWrite r,ServiceProjectService s,FinanceService finance,AppDb db,Access a)=>{await s.Validate(tenant,r,finance);await using var tx=await db.Database.BeginTransactionAsync();var p=new ServiceProject{TenantId=tenant,UnitId=r.UnitId,Name=r.Name.Trim(),Category=r.Category,Description=r.Description,Objectives=r.Objectives,Location=r.Location,ManagerId=r.ManagerId,StartsOn=r.StartsOn,EndsOn=r.EndsOn,CommitteeId=r.CommitteeId,BudgetId=r.BudgetId,EventId=r.EventId,ActivityId=r.ActivityId,AuthorId=a.UserId};db.Add(p);foreach(var id in r.Chapters.Append(r.UnitId).Distinct())db.Add(new ProjectChapter{TenantId=tenant,ProjectId=p.Id,ChapterId=id});a.Audit(tenant,"service.project.requested",p.Id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(p);});
  t.MapGet("/projects/{id:guid}",async(Guid tenant,Guid id,ServiceProjectService s,AppDb db,Access a)=>{var p=await s.Read(tenant,id);var coordinate=await a.Can(tenant,"service.coordinate",p.UnitId);var assignments=db.Set<VolunteerAssignment>().Where(v=>v.TenantId==tenant&&v.ProjectId==id);if(!coordinate)assignments=assignments.Where(v=>db.Memberships.Any(m=>m.Id==v.MembershipId&&db.Persons.Any(person=>person.Id==m.PersonId&&person.UserId==a.UserId)));return Results.Ok(new{project=p,chapters=await(from c in db.Set<ProjectChapter>() join u in db.Units on c.ChapterId equals u.Id where c.TenantId==tenant&&c.ProjectId==id select new{u.Id,u.Name}).ToListAsync(),tasks=await db.Set<ProjectTask>().Where(x=>x.TenantId==tenant&&x.ProjectId==id).OrderBy(x=>x.DueOn).Take(200).ToListAsync(),shifts=await db.Set<VolunteerShift>().Where(x=>x.TenantId==tenant&&x.ProjectId==id).OrderBy(x=>x.StartsAt).Take(200).ToListAsync(),volunteers=await assignments.Take(200).ToListAsync(),impact=await db.Set<ImpactResult>().Where(x=>x.TenantId==tenant&&x.ProjectId==id&&(coordinate||x.Status=="Verified")).Take(200).ToListAsync(),documents=await db.Set<StudioAsset>().Where(x=>x.TenantId==tenant&&x.Kind=="Project:"+id).Select(x=>new{x.Id,x.Name}).Take(100).ToListAsync(),history=await db.Set<CommunityDecision>().Where(d=>d.TenantId==tenant&&d.ResourceId==id).OrderBy(d=>d.At).Select(d=>new{d.Decision,d.Note,d.At}).ToListAsync()});});
  t.MapPut("/projects/{id:guid}",async(Guid tenant,Guid id,ProjectWrite r,ServiceProjectService s,FinanceService finance,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var p=await s.Manage(tenant,id);if(p.Revision!=r.Revision)return Results.Conflict();if(p.Status=="Completed"||p.UnitId!=r.UnitId)throw new DomainException("Completed projects and lead chapters are fixed");await s.Validate(tenant,r,finance);var chapters=r.Chapters.Append(r.UnitId).Distinct().ToArray();var old=await db.Set<ProjectChapter>().Where(c=>c.TenantId==tenant&&c.ProjectId==id).ToListAsync();var removed=old.Where(c=>!chapters.Contains(c.ChapterId)).Select(c=>c.ChapterId).ToArray();if(await db.Set<VolunteerAssignment>().AnyAsync(v=>v.TenantId==tenant&&v.ProjectId==id&&db.Memberships.Any(m=>m.Id==v.MembershipId&&removed.Contains(m.ChapterId))))throw new DomainException("Cannot remove a chapter with volunteer history");db.RemoveRange(old.Where(c=>removed.Contains(c.ChapterId)));foreach(var chapter in chapters.Where(c=>old.All(o=>o.ChapterId!=c)))db.Add(new ProjectChapter{TenantId=tenant,ProjectId=id,ChapterId=chapter});db.Add(new CommunityVersion{TenantId=tenant,ResourceId=id,ActorId=a.UserId,Kind="ServiceProject",Revision=p.Revision,Snapshot=JsonSerializer.Serialize(p)});p.Name=r.Name;p.Description=r.Description;p.Objectives=r.Objectives;p.Location=r.Location;p.Category=r.Category;p.ManagerId=r.ManagerId;p.StartsOn=r.StartsOn;p.EndsOn=r.EndsOn;p.BudgetId=r.BudgetId;p.CommitteeId=r.CommitteeId;p.EventId=r.EventId;p.ActivityId=r.ActivityId;p.Status="Pending Approval";p.AuthorId=a.UserId;p.ApproverId=null;p.Revision++;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(p);});
  t.MapPost("/projects/{id:guid}/decision",async(Guid tenant,Guid id,StudioReview r,ServiceProjectService s,StudioService studio,Access a,AppDb db)=>{var p=await s.Manage(tenant,id,"service.approve");if(p.Status!="Pending Approval"||p.AuthorId==a.UserId)throw new AccessDeniedException();foreach(var chapter in await db.Set<ProjectChapter>().Where(c=>c.TenantId==tenant&&c.ProjectId==id).Select(c=>c.ChapterId).ToListAsync())await a.Require(tenant,"service.approve",chapter);studio.Decision(tenant,id,p.UnitId,"ServiceProject",r);p.Status=r.Decision=="Approve"?"Approved":"Rejected";p.ApproverId=a.UserId;p.Revision++;await db.SaveChangesAsync();return Results.Ok(p);});
  t.MapPost("/projects/{id:guid}/complete",async(Guid tenant,Guid id,ServiceProjectService s,AppDb db,Access a)=>{var p=await s.Manage(tenant,id);if(p.Status!="Approved"||await db.Set<ProjectTask>().AnyAsync(x=>x.ProjectId==id&&x.Status!="Completed"))throw new DomainException("Approve the project and finish its tasks first");p.Status="Completed";p.Revision++;a.Audit(tenant,"service.project.completed",id);await db.SaveChangesAsync();return Results.Ok(p);});
  t.MapPost("/projects/{id:guid}/tasks",async(Guid tenant,Guid id,ProjectTask r,ServiceProjectService s,AppDb db,Access a)=>{var p=await s.Manage(tenant,id);if(r.Title.Length is <3 or >300||r.DueOn<p.StartsOn||r.DueOn>p.EndsOn)throw new DomainException("Enter a task and due date within the project");if(r.MembershipId!=null)await s.Participant(p,await s.Member(tenant,r.MembershipId.Value));var task=new ProjectTask{TenantId=tenant,ProjectId=id,Title=r.Title,MembershipId=r.MembershipId,DueOn=r.DueOn};db.Add(task);a.Audit(tenant,"service.task.created",task.Id);await db.SaveChangesAsync();return Results.Ok(task);});
  t.MapPut("/tasks/{id:guid}",async(Guid tenant,Guid id,ProjectTask r,ServiceProjectService s,AppDb db,Access a)=>{var task=await db.Set<ProjectTask>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id)??throw new AccessDeniedException();await s.Manage(tenant,task.ProjectId);if(r.Revision!=task.Revision)return Results.Conflict();if(r.Status is not("Open" or "In Progress" or "Completed"))throw new DomainException("Choose a task status");task.Status=r.Status;task.Revision++;a.Audit(tenant,"service.task.updated",id);await db.SaveChangesAsync();return Results.Ok(task);});
  t.MapGet("/volunteers",async(Guid tenant,Guid? workspace,AppDb db,Access a)=>{var units=a.InWorkspace(a.Visible(tenant,"service.coordinate"),tenant,workspace).Select(u=>u.Id);return await(from v in db.Set<VolunteerProfile>() join m in db.Memberships on v.MembershipId equals m.Id join p in db.Persons on m.PersonId equals p.Id where v.TenantId==tenant&&(p.UserId==a.UserId||units.Contains(m.ChapterId)) orderby p.FullName select new{v.Id,v.MembershipId,p.FullName,m.Number,m.ChapterId,v.Skills,v.Interests,v.Availability,v.PreferredTypes,v.Active}).Take(200).ToListAsync();});
  t.MapPut("/volunteers/{membership:guid}",async(Guid tenant,Guid membership,VolunteerProfile r,ServiceProjectService s,AppDb db)=>{await s.Member(tenant,membership,true);if(new[]{r.Skills,r.Interests,r.Availability,r.PreferredTypes}.Any(v=>v.Length>2000))throw new DomainException("Volunteer profile fields are limited to 2,000 characters");var profile=await db.Set<VolunteerProfile>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.MembershipId==membership);if(profile==null){profile=new(){TenantId=tenant,MembershipId=membership};db.Add(profile);}profile.Skills=r.Skills;profile.Interests=r.Interests;profile.Availability=r.Availability;profile.PreferredTypes=r.PreferredTypes;profile.Active=r.Active;await db.SaveChangesAsync();return Results.Ok(profile);});
  t.MapPost("/projects/{id:guid}/volunteers",async(Guid tenant,Guid id,VolunteerAssignment r,ServiceProjectService s,AppDb db)=>{var p=await s.Read(tenant,id);var member=await s.Member(tenant,r.MembershipId,true);await s.Participant(p,member);if(p.Status!="Approved"||p.EndsOn<FinanceService.Today)throw new DomainException("Apply to a current approved opportunity");var previous=await db.Set<VolunteerAssignment>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.ProjectId==id&&v.MembershipId==member.Id);if(previous!=null)return Results.Ok(previous);var x=new VolunteerAssignment{TenantId=tenant,ProjectId=id,MembershipId=member.Id};db.Add(x);await db.SaveChangesAsync();return Results.Ok(x);});
  t.MapPost("/assignments/{id:guid}/decision",async(Guid tenant,Guid id,StudioReview r,ServiceProjectService s,AppDb db,Access a)=>{var v=await db.Set<VolunteerAssignment>().SingleOrDefaultAsync(v=>v.Id==id&&v.TenantId==tenant&&v.Status=="Applied")??throw new DomainException("Choose a pending volunteer");await s.Manage(tenant,v.ProjectId,"service.coordinate");if(r.Decision is not("Approve" or "Reject"))throw new DomainException("Choose Approve or Reject");await s.Member(tenant,v.MembershipId);v.Status=r.Decision=="Approve"?"Approved":"Rejected";v.CoordinatorId=a.UserId;a.Audit(tenant,"volunteer.assignment.reviewed",id,new{r.Decision});await db.SaveChangesAsync();return Results.Ok(v);});
  t.MapPost("/projects/{id:guid}/shifts",async(Guid tenant,Guid id,VolunteerShift r,ServiceProjectService s,AppDb db)=>{var p=await s.Manage(tenant,id,"service.coordinate");if(p.Status!="Approved"||r.Name.Length is <3 or >160||r.Capacity is <1 or >10000||r.EndsAt<=r.StartsAt||r.EndsAt-r.StartsAt>TimeSpan.FromHours(24)||DateOnly.FromDateTime(r.StartsAt.UtcDateTime)<p.StartsOn||DateOnly.FromDateTime(r.EndsAt.UtcDateTime)>p.EndsOn)throw new DomainException("Choose a named shift up to 24 hours within an approved project");var shift=new VolunteerShift{TenantId=tenant,ProjectId=id,Name=r.Name,StartsAt=r.StartsAt.ToUniversalTime(),EndsAt=r.EndsAt.ToUniversalTime(),Capacity=r.Capacity};db.Add(shift);await db.SaveChangesAsync();return Results.Ok(shift);});
  t.MapPost("/shifts/{id:guid}/attendance",RecordAttendance);
  t.MapGet("/hours",async(Guid tenant,Guid? workspace,AppDb db,Access a)=>{var units=a.InWorkspace(a.Visible(tenant,"service.coordinate"),tenant,workspace).Select(u=>u.Id);return await(from v in db.Set<VolunteerAttendance>() join m in db.Memberships on v.MembershipId equals m.Id join p in db.Persons on m.PersonId equals p.Id where v.TenantId==tenant&&(p.UserId==a.UserId||units.Contains(m.ChapterId)) orderby v.CheckedIn descending select new{v.Id,v.ShiftId,v.MembershipId,p.FullName,v.CheckedIn,v.CheckedOut,v.Hours,v.Status,v.RecorderId,v.VerifierId,v.Note}).Take(200).ToListAsync();});
  t.MapPost("/hours/{id:guid}/decision",async(Guid tenant,Guid id,StudioReview r,ServiceProjectService s,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var attendance=await db.Set<VolunteerAttendance>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.Id==id&&v.Status=="Pending Verification"&&v.CheckedOut!=null)??throw new DomainException("Check out before verification");var shift=await db.Set<VolunteerShift>().SingleAsync(v=>v.Id==attendance.ShiftId&&v.TenantId==tenant);await s.Manage(tenant,shift.ProjectId,"service.verify");if(attendance.RecorderId==a.UserId||await db.Memberships.AnyAsync(m=>m.Id==attendance.MembershipId&&db.Persons.Any(p=>p.Id==m.PersonId&&p.UserId==a.UserId)))throw new AccessDeniedException();if(r.Decision is not("Approve" or "Reject"))throw new DomainException("Choose Approve or Reject");attendance.Status=r.Decision=="Approve"?"Verified":"Rejected";attendance.VerifierId=a.UserId;attendance.Note=r.Note;a.Audit(tenant,"volunteer.hours.reviewed",id,new{r.Decision,attendance.Hours});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(attendance);});
  t.MapPut("/hours/{id:guid}/correction",async(Guid tenant,Guid id,VolunteerCorrection r,ServiceProjectService s,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var row=await db.Set<VolunteerAttendance>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.Id==id)??throw new AccessDeniedException();var shift=await db.Set<VolunteerShift>().SingleAsync(v=>v.TenantId==tenant&&v.Id==row.ShiftId);await s.Manage(tenant,shift.ProjectId,"service.coordinate");if(row.CheckedIn!=r.ExpectedCheckedIn||row.CheckedOut!=r.ExpectedCheckedOut)return Results.Conflict(new{title="Attendance changed; refresh before correcting"});if(r.Reason.Length is <3 or >2000||r.CheckedIn<shift.StartsAt||r.CheckedOut>shift.EndsAt||r.CheckedOut<=r.CheckedIn||r.CheckedOut>DateTimeOffset.UtcNow.AddMinutes(1))throw new DomainException("Explain the correction and use actual times inside the shift");if(await db.Set<VolunteerAttendance>().AnyAsync(v=>v.TenantId==tenant&&v.Id!=id&&v.MembershipId==row.MembershipId&&v.Status!="Rejected"&&(v.CheckedOut==null||v.CheckedOut>r.CheckedIn)&&v.CheckedIn<r.CheckedOut))throw new DomainException("Corrected attendance overlaps another shift");var revision=await db.Set<CommunityVersion>().CountAsync(v=>v.TenantId==tenant&&v.ResourceId==id&&v.Kind=="VolunteerCorrection");db.Add(new CommunityVersion{TenantId=tenant,ResourceId=id,ActorId=a.UserId,Kind="VolunteerCorrection",Revision=revision,Snapshot=JsonSerializer.Serialize(row)});row.CheckedIn=r.CheckedIn.ToUniversalTime();row.CheckedOut=r.CheckedOut.ToUniversalTime();row.Hours=Math.Round((decimal)(r.CheckedOut-r.CheckedIn).Ticks/TimeSpan.TicksPerHour,4,MidpointRounding.AwayFromZero);row.Status="Pending Verification";row.RecorderId=a.UserId;row.VerifierId=null;row.Note=r.Reason;a.Audit(tenant,"volunteer.hours.correction.requested",id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(row);});
  MapImpact(t);
 }
 static async Task<IResult> RecordAttendance(Guid tenant,Guid id,VolunteerCheck r,ServiceProjectService s,AppDb db,Access a){await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var shift=await db.Set<VolunteerShift>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.Id==id)??throw new AccessDeniedException();var project=await s.Read(tenant,shift.ProjectId);var member=await s.Member(tenant,r.MembershipId);await s.Participant(project,member);var own=await db.Persons.AnyAsync(p=>p.Id==member.PersonId&&p.UserId==a.UserId);if(!own)await a.Require(tenant,"service.coordinate",project.UnitId);if(!await db.Set<VolunteerAssignment>().AnyAsync(v=>v.TenantId==tenant&&v.ProjectId==project.Id&&v.MembershipId==member.Id&&v.Status=="Approved")||project.Status!="Approved")throw new DomainException("An approved assignment in an active project is required");var now=DateTimeOffset.UtcNow;var start=own?now:r.CheckedIn??now;var end=own?(r.CheckedOut!=null?now:(DateTimeOffset?)null):r.CheckedOut;if(start<shift.StartsAt||start>shift.EndsAt||start>now.AddMinutes(1)||end!=null&&(end<start||end>shift.EndsAt||end>now.AddMinutes(1)))throw new DomainException("Attendance times must be actual times inside this shift");var row=await db.Set<VolunteerAttendance>().SingleOrDefaultAsync(v=>v.TenantId==tenant&&v.ShiftId==id&&v.MembershipId==member.Id);if(row==null){if(await db.Set<VolunteerAttendance>().CountAsync(v=>v.ShiftId==id&&v.Status!="Rejected")>=shift.Capacity)throw new DomainException("Shift capacity reached");if(await db.Set<VolunteerAttendance>().AnyAsync(v=>v.TenantId==tenant&&v.MembershipId==member.Id&&v.Status!="Rejected"&&(v.CheckedOut==null||v.CheckedOut>start)&&v.CheckedIn<(end??shift.EndsAt)))throw new DomainException("Volunteer attendance overlaps an existing shift");row=new(){TenantId=tenant,ShiftId=id,MembershipId=member.Id,CheckedIn=start,RecorderId=a.UserId};db.Add(row);}else if(row.Status!="Pending Verification"||row.CheckedOut!=null)throw new DomainException("Recorded attendance cannot be silently overwritten");if(end!=null){if(end<=row.CheckedIn)throw new DomainException("Checkout must follow check-in");row.CheckedOut=end;row.Hours=Math.Round((decimal)(end.Value-row.CheckedIn).Ticks/TimeSpan.TicksPerHour,4,MidpointRounding.AwayFromZero);}row.Note=r.Note.Length<=2000?r.Note:throw new DomainException("Note exceeds 2,000 characters");a.Audit(tenant,"volunteer.attendance.recorded",row.Id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(row);}
 static void MapImpact(RouteGroupBuilder t){
  t.MapGet("/metrics",async(Guid tenant,AppDb db)=>await db.Set<ImpactMetric>().Where(m=>m.TenantId==tenant).OrderBy(m=>m.Name).ToListAsync());
  t.MapPost("/metrics",async(Guid tenant,ImpactMetric r,AppDb db,Access a)=>{await a.Require(tenant,"service.manage");if(r.Name.Length is <2 or >120||r.Unit.Length is <1 or >60||r.Category.Length>120||r.Aggregation is not("Sum" or "Max" or "Count"))throw new DomainException("Define a name, unit and supported aggregation method");var metric=new ImpactMetric{TenantId=tenant,Name=r.Name,Unit=r.Unit,Category=r.Category,Aggregation=r.Aggregation,EvidenceRequired=r.EvidenceRequired};db.Add(metric);await db.SaveChangesAsync();return Results.Ok(metric);});
  t.MapPost("/projects/{id:guid}/impact",async(Guid tenant,Guid id,ImpactWrite r,AppDb db,Access a,ServiceProjectService s)=>{var p=await s.Manage(tenant,id,"service.coordinate");if(p.Status is not("Approved" or "Completed"))throw new DomainException("Record outcomes for an approved project");var metric=await db.Set<ImpactMetric>().SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==r.MetricId&&m.Active)??throw new DomainException("Choose an active impact metric");if(r.Value<0||r.Value>1000000000||r.OutcomeKey.Length is <3 or >160||r.Evidence.Length>4000||metric.EvidenceRequired&&string.IsNullOrWhiteSpace(r.Evidence)&&r.EvidenceId==null||metric.Aggregation=="Count"&&r.Value!=1)throw new DomainException("Enter a non-negative outcome, unique evidence key and required evidence; Count metrics record one outcome");if(r.EvidenceId!=null&&!await db.Set<StudioAsset>().AnyAsync(x=>x.TenantId==tenant&&x.Id==r.EvidenceId&&x.Kind=="Project:"+id))throw new AccessDeniedException();var result=new ImpactResult{TenantId=tenant,ProjectId=id,MetricId=r.MetricId,OutcomeKey=r.OutcomeKey.Trim().ToLowerInvariant(),Value=r.Value,Evidence=r.Evidence,EvidenceId=r.EvidenceId,AuthorId=a.UserId};db.Add(result);a.Audit(tenant,"impact.submitted",result.Id);await db.SaveChangesAsync();return Results.Ok(result);});
  t.MapPost("/impact/{id:guid}/decision",async(Guid tenant,Guid id,StudioReview r,AppDb db,Access a,ServiceProjectService s)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var result=await db.Set<ImpactResult>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id&&x.Status=="Pending Verification")??throw new DomainException("Choose a pending impact result");await s.Manage(tenant,result.ProjectId,"service.verify");if(result.AuthorId==a.UserId)throw new AccessDeniedException();if(r.Decision is not("Approve" or "Reject")||r.Note.Length>2000)throw new DomainException("Choose Approve or Reject and a bounded note");result.Status=r.Decision=="Approve"?"Verified":"Rejected";result.VerifierId=a.UserId;result.Note=r.Note;a.Audit(tenant,"impact.reviewed",id,new{r.Decision,result.Value});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(result);});
  t.MapPut("/impact/{id:guid}/correction",async(Guid tenant,Guid id,ImpactResult r,AppDb db,Access a,ServiceProjectService s)=>{var result=await db.Set<ImpactResult>().SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.Id==id)??throw new AccessDeniedException();await s.Manage(tenant,result.ProjectId,"service.coordinate");if(result.Revision!=r.Revision)return Results.Conflict();var metric=await db.Set<ImpactMetric>().SingleAsync(m=>m.TenantId==tenant&&m.Id==result.MetricId);if(r.Value<0||r.Value>1000000000||r.Evidence.Length is <3 or >4000||r.Note.Length is <3 or >2000||metric.Aggregation=="Count"&&r.Value!=1)throw new DomainException("Explain the correction with valid evidence/value");db.Add(new CommunityVersion{TenantId=tenant,Kind="ImpactCorrection",ResourceId=id,ActorId=a.UserId,Revision=result.Revision,Snapshot=JsonSerializer.Serialize(result)});result.Value=r.Value;result.Evidence=r.Evidence;result.Note=r.Note;result.Status="Pending Verification";result.AuthorId=a.UserId;result.VerifierId=null;result.Revision++;a.Audit(tenant,"impact.correction.requested",id);await db.SaveChangesAsync();return Results.Ok(result);});
  t.MapGet("/impact",async(Guid tenant,Guid? workspace,ServiceProjectService s,AppDb db)=>{var projects=s.Visible(tenant,workspace).Select(p=>p.Id);var q=db.Set<ImpactResult>().Where(x=>x.TenantId==tenant&&x.Status=="Verified"&&projects.Contains(x.ProjectId));return Results.Ok(new{verifiedOnly=true,projects=await projects.CountAsync(),metrics=await(from x in q join metric in db.Set<ImpactMetric>() on x.MetricId equals metric.Id group x by new{metric.Id,metric.Name,metric.Unit,metric.Aggregation} into g select new{g.Key.Id,g.Key.Name,g.Key.Unit,g.Key.Aggregation,value=g.Key.Aggregation=="Max"?g.Max(x=>x.Value):g.Key.Aggregation=="Count"?g.Count():g.Sum(x=>x.Value),records=g.Count()}).ToListAsync(),verifiedHours=await db.Set<VolunteerAttendance>().Where(v=>v.TenantId==tenant&&v.Status=="Verified"&&db.Set<VolunteerShift>().Any(s=>s.Id==v.ShiftId&&projects.Contains(s.ProjectId))).SumAsync(v=>v.Hours)});});
  t.MapPost("/projects/{id:guid}/documents",async(Guid tenant,Guid id,HttpRequest request,ServiceProjectService s,AppDb db,Access a,IObjectStore store)=>{var p=await s.Manage(tenant,id);if(request.ContentLength is null or >2097152)throw new DomainException("Upload a PNG evidence image smaller than 2 MB");using var input=new MemoryStream();await request.Body.CopyToAsync(input);var bytes=AssetEndpoints.SanitizePng(input.ToArray());var x=new StudioAsset{TenantId=tenant,UnitId=p.UnitId,Kind="Project:"+id,Name=Path.GetFileName(request.Headers["X-Filename"].ToString())[..Math.Min(160,Path.GetFileName(request.Headers["X-Filename"].ToString()).Length)],Length=bytes.Length,AuthorId=a.UserId};await store.Put(tenant,x.Id,bytes);db.Add(x);await db.SaveChangesAsync();return Results.Ok(new{x.Id,x.Name});});
  t.MapGet("/projects/{id:guid}/documents/{file:guid}",async(Guid tenant,Guid id,Guid file,ServiceProjectService s,AppDb db,IObjectStore store)=>{await s.Read(tenant,id);if(!await db.Set<StudioAsset>().AnyAsync(x=>x.TenantId==tenant&&x.Id==file&&x.Kind=="Project:"+id))throw new AccessDeniedException();return Results.File(store.Open(tenant,file),"image/png");});
 }
}
